func TestAWSAnthropic_RequestBody_AnthropicVersion(t *testing.T) {
	t.Run("default bedrock version present in body", func(t *testing.T) {
		raw, _ := json.Marshal(openai.ChatCompletionRequest{
			Model: "anthropic.claude-3-5-sonnet-20241022-v2:0",
			Messages: []openai.ChatCompletionMessageParamUnion{
				{OfUser: &openai.ChatCompletionUserMessageParam{Role: openai.ChatMessageRoleUser, Content: openai.StringOrUserRoleContentUnion{Value: "hello"}}},
			},
		})
		o := NewChatCompletionOpenAIToAWSAnthropicTranslator(ProviderConfig{})
		_, body, err := o.RequestBody(raw)
		require.NoError(t, err)
		require.NotNil(t, body)
		var m map[string]json.RawMessage
		require.NoError(t, json.Unmarshal(body, &m))
		var ver string
		require.NoError(t, json.Unmarshal(m["anthropic_version"], &ver))
		require.Equal(t, BedrockDefaultVersion, ver)
	})

	t.Run("custom anthropic_version from config", func(t *testing.T) {
		raw, _ := json.Marshal(openai.ChatCompletionRequest{
			Model: "anthropic.claude-3-5-sonnet-20241022-v2:0",
			Messages: []openai.ChatCompletionMessageParamUnion{
				{OfUser: &openai.ChatCompletionUserMessageParam{Role: openai.ChatMessageRoleUser, Content: openai.StringOrUserRoleContentUnion{Value: "hello"}}},
			},
		})
		o := NewChatCompletionOpenAIToAWSAnthropicTranslator(ProviderConfig{
			Extra: map[string]string{"anthropic_version": "bedrock-2024-01-01"},
		})
		_, body, err := o.RequestBody(raw)
		require.NoError(t, err)
		require.NotNil(t, body)
		var m map[string]json.RawMessage
		require.NoError(t, json.Unmarshal(body, &m))
		var ver string
		require.NoError(t, json.Unmarshal(m["anthropic_version"], &ver))
		require.Equal(t, "bedrock-2024-01-01", ver)
	})
}

